// Deterministic pseudo-values - HANDOVER §5.6.
//
// The artifact contains NO random number generation. Every value that varies -
// a seeded score, a near-miss label, a token count, a judge payload - comes
// from a stable string hash of an identifier, so the same input always
// produces the same output and a defect is always reproducible. Time is the
// only exception: a countdown and a submission stamp read the clock.

/// FNV-1a, 32-bit. Chosen because it is short, has no dependencies, and gives
/// a well-spread value for the short identifier strings the seed data uses.
///
/// The multiply is SPLIT into 16-bit halves rather than written as
/// `h * 0x01000193`. That is not a micro-optimisation: on the web a Dart `int`
/// is a JavaScript double, and `0xFFFFFFFF * 0x01000193` is about 7.2e16,
/// past the 2^53 mark where doubles stop being exact. The naive form therefore
/// produces DIFFERENT hashes on the web from the ones the VM computes, which
/// silently breaks the determinism the whole seed depends on - a token
/// generated by a test would not resolve in the browser.
///
/// Splitting keeps every intermediate under about 1.1e12, so the result is
/// exact mod 2^32 on every platform.
int stableHash(String s) {
  const int prime = 0x01000193;
  int h = 0x811c9dc5;
  for (int i = 0; i < s.length; i++) {
    h ^= s.codeUnitAt(i);
    final int lo = h & 0xFFFF;
    final int hi = (h >> 16) & 0xFFFF;
    h = ((lo * prime) + (((hi * prime) & 0xFFFF) << 16)) & 0xFFFFFFFF;
  }
  return h;
}

/// A stable value in `[min, max)` for [seed].
int seededInt(String seed, int min, int max) {
  if (max <= min) return min;
  return min + (stableHash(seed) % (max - min));
}

/// A stable value in `[0, 1)` for [seed].
double seededUnit(String seed) => (stableHash(seed) % 10000) / 10000.0;

/// A stable value in `[min, max)` for [seed].
double seededDouble(String seed, double min, double max) =>
    min + seededUnit(seed) * (max - min);

/// A stable pick from [options].
T seededPick<T>(String seed, List<T> options) =>
    options[stableHash(seed) % options.length];

/// A stable boolean that is true [pct] percent of the time.
bool seededBool(String seed, int pct) => (stableHash(seed) % 100) < pct;
